<h1>Setlist</h1><form method="get" class="cari"><input type="hidden" name="r" value="setlist"><select name="event_id" required><option value="">Pilih event</option><?php foreach($events as $id=>$name): ?><option value="<?= (int)$id ?>"<?= $eventId===$id?' selected':'' ?>><?= e($name) ?></option><?php endforeach; ?></select><button>Buka</button></form><?php if($eventId!==null): ?><div class="kartu"><ol><?php foreach($items as $item): ?><li><?= e($item['title']) ?><?= db_bool($item['is_encore'])?' [Encore]':'' ?> <form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="remove"><input type="hidden" name="position" value="<?= (int)$item['position'] ?>"><button class="hapus">Hapus</button></form></li><?php endforeach; ?></ol><?php if(!$items): ?><p>Setlist kosong.</p><?php endif; ?></div><form method="post" class="cari kartu"><?= csrf_field() ?><input type="hidden" name="do" value="add"><select name="track_id" required><?php foreach($tracks as $track): ?><option value="<?= (int)$track['id'] ?>"><?= e($track['title']) ?></option><?php endforeach; ?></select><label><input type="checkbox" name="is_encore" value="1"> Encore</label><button class="btn">Tambah Lagu</button></form><?php endif; ?>
